"            logger.warning(f\"Sessão do módulo {module} expirada. Iniciando renovação automática via Playwright...\")\n            \n            try:\n                db.insert_alert({\n                    \"event_id\":  self.event_id,\n                    \"level\":     \"GLOBAL\",\n                    \"severity\":  \"WARNING\",\n                    \"site_id\":   \"\",\n                    \"cell_id\":   \"\",\n                    \"message\":   f\"Sessão do iManager ({module}) expirada. Iniciando renovação automática via Playwright...\",\n                    \"timestamp\": datetime.utcnow().isoformat(),\n                })\n            except Exception as ae:\n                logger.error(f\"Erro ao inserir alerta de expiração no banco: {ae}\")\n\n            try:\n                import subprocess\n                import sys\n                script_path = Path(__file__).parent.parent / \"scratch\" / \"get_session.py\"\n                res = subprocess.run(\n                    [sys.executable, str(script_path), \"--headless\"],\n                    capture_output=True,\n                    text=True,\n                    check=True\n                )\n                logger.info(\"Playwright renovou a sessão com sucesso.\")\n                logger.debug(f\"Saída do Playwright: {res.stdout}\")\n            except Exception as e:\n                logger.error(f\"Erro ao executar renovação de sessão: {e}\")\n                if hasattr(e, 'stderr') and e.stderr:\n                    logger.error(f\"Stderr do Playwright: {e.stderr}\")\n            \n            self._session_monitoring = None\n            self._session_trace = None"